  INSERT INTO vr_rollcalls (measure_id, chamber, congress, session, roll_number, vote_date, question, action_type, result, required_majority, totals, source_url, source_label)
  VALUES (m_119_s_amdt_5813, 'senate', 119, 2, 156, TIMESTAMPTZ '2026-06-05T02:21:00-04:00', 'On the Amendment S.Amdt. 5813 to S.Amdt. 5453 to S. 2 (No short title on file)', 'amendment', 'rejected', 'simple',
    '{"yea":47,"nay":52,"present":0,"notVoting":1,"byParty":{"D":{"yea":44,"nay":0},"R":{"yea":1,"nay":52},"I":{"yea":2,"nay":0}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00156.htm', 'U.S. Senate')
  ON CONFLICT (chamber, congress, session, roll_number) DO NOTHING;
