    '{"yea":45,"nay":53,"present":1,"notVoting":1,"byParty":{"D":{"yea":43,"nay":0},"R":{"yea":0,"nay":53},"I":{"yea":2,"nay":0}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00160.htm', 'U.S. Senate')
  ON CONFLICT (chamber, congress, session, roll_number) DO NOTHING;
