  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the provision-level rationale and a primary
  -- source on every row — scripts/test-mapping-discipline.mjs requires both. The seed is
  -- what POST /api/vr-ingest/seed-issues re-asserts, so a mapping this migration writes and
  -- the seed does not carry would be undone by the next ingest; these agree by construction,
  -- because the generator reads the seed rather than restating it.

  -- S. 2 (119th) — deportations yea_supports w100 PRIMARY, border_security yea_supports w90, immig_fentanyl yea_supports w50, tough_on_crime yea_supports w40
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_2, 'deportations', 100, true, 'yea_supports',
      'Title II is the largest part of the Act and is interior immigration enforcement in terms: Sec. 201 appropriates $13.020 billion to CBP "in order to carry out immigration enforcement activities", and Sec. 202 appropriates $31.075 billion to ICE across nine purposes that name removal directly — transportation costs "associated with alien departure or removal operations" (2), information technology, facility and fleet sustainment each "to support enforcement and removal operations" (3)-(5), and attorneys in the Office of the Principal Legal Advisor "to represent the Department in immigration enforcement and removal proceedings" (7). Paragraph (9) sets aside not less than $350,000,000 for detainer management, custodial transfer and arrests of covered unlawful aliens, and (9)(C) forbids those funds from being used to release, parole, place on alternatives to detention or otherwise facilitate the release into the community of anyone encountered. A yea funds removal operations at $44.095 billion, 63 percent of the Act. Primary at 100: this is what the bill is.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s2enr/html/BILLS-119s2enr.htm'),
    (m_119_s_2, 'border_security', 90, false, 'yea_supports',
      'Sec. 101 appropriates $9.550 billion to hire, pay, train and equip Border Patrol agents and Border Patrol support personnel; Sec. 103 appropriates $3.450 billion for nonintrusive inspection equipment at ports of entry and along the southwest, northern and maritime borders, Air and Marine platforms for rapid response, border surveillance technology upgrades, and the biometric entry and exit system under 8 U.S.C. 1365b; and Secs. 104 and 203 add $5.000 billion for the purposes of their respective titles. A yea funds border personnel and border technology at $26.020 billion counting Sec. 201''s CBP hiring. Weighted 90 rather than 100 only because deportations carries the larger share and is the primary; this is far more border-specific than the Laken Riley Act''s border_security mapping (70), which rested on a detention mandate rather than on any border appropriation.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s2enr/html/BILLS-119s2enr.htm'),
    (m_119_s_2, 'immig_fentanyl', 50, false, 'yea_supports',
      'Two of Sec. 103(a)''s six enumerated purposes are narcotics interdiction, and the statute names the drug: paragraph (1) funds new nonintrusive inspection equipment "including artificial intelligence, machine learning, and other innovative technologies … to combat the entry or exit of illicit narcotics at ports of entry and along the southwest, northern, and maritime borders", and paragraph (5) funds "[e]nhancing border security by combating drug trafficking, including fentanyl and its precursor chemicals" at those same borders. A yea funds interdiction capability aimed at fentanyl and its precursors. Weighted 50: above the FY2026 NDAA''s immig_fentanyl mapping (40), because that one worked through sanctions and reporting while this is direct detection and interdiction money, and well below the enforcement axes, because Sec. 103 is $3.450 billion — 5 percent of the Act — and fentanyl is two of its six purposes.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s2enr/html/BILLS-119s2enr.htm'),
    (m_119_s_2, 'tough_on_crime', 40, false, 'yea_supports',
      'Sec. 102 appropriates $7.450 billion to hire, pay, train and equip Homeland Security Investigations agents and support personnel, and closes with an express carve-out: "funds provided in this section shall be used for functions other than those related to Homeland Security Investigations'' immigration enforcement and customs enforcement missions." That makes it, by the statute''s own terms, $7.450 billion of federal CRIMINAL investigation capacity rather than immigration money, and it earmarks $108,500,000 of it for additional child exploitation investigators and forensics analysts at the Victim Identification Laboratory of the Child Exploitation Investigations Unit and at the Special Agent in Charge offices, plus training of State and local law enforcement, "to support the identification and rescue of victims of child sexual exploitation and abuse", within the HSI Cyber Crimes Center. A yea funds investigators for those crimes. Weighted 40 and not higher: Sec. 102 is 10.7 percent of the Act, the members who voted no did so on the enforcement titles rather than on this section, and it adds investigative staffing rather than changing any offence or sentence. The related criminal-alien definitions in Sec. 202(9)(D) are deliberately NOT counted here — they are already carried by deportations, and counting them twice would inflate this axis.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s2enr/html/BILLS-119s2enr.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.Amdt. 5813 (119th) — immigration_reform yea_supports w100 PRIMARY
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_5813, 'immigration_reform', 100, true, 'yea_supports',
      'The amendment''s stated purpose is its entire substance: "To make funds available for the timely adjudication of DACA renewal applications." A yea funds processing of renewals under the existing Deferred Action for Childhood Arrivals policy, whose recipients lose work authorisation and protection from removal when a renewal lapses in the backlog; a nay leaves the bill''s $69.545 billion entirely with border and immigration enforcement. immigration_reform is the chip "Create earned pathways to citizenship for long-settled immigrants" and its keyword set names DACA and Dreamers directly. Primary at 100 because a single-purpose amendment has no second axis, with one honest qualification recorded here: the amendment funds ADJUDICATION of an existing deferred-action policy and creates no pathway of its own, so it tests support for protecting long-settled DACA recipients rather than support for a new status. Rejected 47-52, so no renewal-adjudication funding is in Public Law 119-98.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00156.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.Amdt. 5463 (119th) — back_police yea_supports w100 PRIMARY
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_5463, 'back_police', 100, true, 'yea_supports',
      'The amendment''s stated purpose is its entire substance: "To appropriate amounts for local law enforcement hiring programs." A yea adds funding for State and local police staffing to a bill whose $69.545 billion otherwise goes entirely to federal Customs and Border Protection and Immigration and Customs Enforcement; a nay leaves it out. back_police is the chip "Fund police and impose tougher penalties for violent crime", and this amendment is the funding half of it in isolation — no offence, penalty or sentence is touched. Primary at 100 because a single-purpose amendment has no second axis. Rejected, so no local hiring line is in Public Law 119-98.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00160.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in every immigration mapping earlier passes wrote and stop meaning anything.
--
-- Roll-call and mapping counts assert equality, not >=, because every row in this pass
-- is new: nothing here re-emits a mapping another migration already wrote, which is what
-- forced the >= in the landmark pass. Member-vote counts still assert >=, because a
-- later and wider roster expansion legitimately tops these rolls up beyond what this
-- seed carried and a re-run must not then fail. The orphan check covers all four rolls
-- for the same reason the landmark pass had to exclude three of its nine: there is no
-- pre-existing attribution here to be unfair to.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_measures integer;
  n_parent integer;
  n_enacted integer;
  n_s2_senate integer;
  n_s2_house integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 2::integer, 156::integer),
    ('senate'::text, 119::integer, 2::integer, 160::integer),
    ('senate'::text, 119::integer, 2::integer, 163::integer),
    ('house'::text, 119::integer, 2::integer, 214::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), mine (congress, chamber, number) AS (VALUES
    (119::integer, 'senate'::text, 'S. 2'::text),
    (119::integer, 'senate'::text, 'S.Amdt. 5813'::text),
    (119::integer, 'senate'::text, 'S.Amdt. 5463'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.congress = k.congress AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'andy_kim', 'aoc', 'barrasso', 'bennie_thompson', 'bmoore', 'boebert', 'booker', 'brian_mast', 'britt', 'bruce_westerman', 'chris_murphy', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'dan_goldman', 'don_bacon', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'graham', 'grassley', 'greg_landsman', 'haley_stevens', 'hawley', 'jake_auchincloss', 'jason_smith', 'jayapal', 'jeffries', 'jim_jordan', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'khanna', 'lankford', 'lee', 'mariannette_miller_meeks', 'mark_kelly', 'massie', 'maxine_waters', 'mcconnell', 'meeks', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_simpson', 'mike_waltz', 'mtg', 'murkowski', 'omar', 'owens', 'rand_paul', 'reed', 'rick_crawford', 'risch', 'rob_bresnahan', 'rosen', 'rubio', 'ryan_mackenzie', 'sanders', 'scalise', 'schiff', 'schumer', 'scott_perry', 'shaheen', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'tgabbard', 'thune', 'tim_scott', 'tlaib', 'tom_cole', 'tom_suozzi', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'warnock', 'warren', 'zeldin'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('back_police', 'border_security', 'deportations', 'immig_fentanyl', 'immigration_reform', 'tough_on_crime')),
         (SELECT count(*) FROM measure_ids),
         (SELECT count(*) FROM vr_measures a JOIN vr_measures p ON p.id = a.parent_id
           WHERE a.congress = 119 AND a.chamber = 'senate'
             AND a.number IN ('S.Amdt. 5813', 'S.Amdt. 5463')
             AND p.congress = 119 AND p.chamber = 'senate' AND p.number = 'S. 2'),
         (SELECT count(*) FROM vr_measures m WHERE m.congress = 119 AND m.chamber = 'senate'
            AND m.number = 'S. 2' AND m.status = 'enacted'
            AND m.external_ids ->> 'publicLaw' = '119-98'),
         (SELECT count(*) FROM vr_member_votes v JOIN vr_rollcalls r ON r.id = v.rollcall_id
           WHERE r.chamber = 'senate' AND r.congress = 119 AND r.session = 2 AND r.roll_number = 163),
         (SELECT count(*) FROM vr_member_votes v JOIN vr_rollcalls r ON r.id = v.rollcall_id
           WHERE r.chamber = 'house' AND r.congress = 119 AND r.session = 2 AND r.roll_number = 214)
    INTO n_rolls, n_votes, n_orphan, n_issues, n_measures, n_parent, n_enacted, n_s2_senate, n_s2_house;

  RAISE NOTICE 'Secure America pass: % roll calls, % member votes, % issue mappings, % measures', n_rolls, n_votes, n_issues, n_measures;
  RAISE NOTICE 'Secure America pass: S. 2 passage attributed on % Senate and % House member votes', n_s2_senate, n_s2_house;

  IF n_rolls <> 4 THEN
    RAISE EXCEPTION 'Secure America pass: expected 4 roll calls, found %', n_rolls;
  END IF;
  IF n_measures <> 3 THEN
    RAISE EXCEPTION 'Secure America pass: expected 3 measure rows, found % — (congress, number) is not unique, so a duplicate is possible', n_measures;
  END IF;
  IF n_votes < 170 THEN
    RAISE EXCEPTION 'Secure America pass: expected at least 170 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Secure America pass: % member vote(s) carry a politician_id outside db/vr-member-map.json', n_orphan;
  END IF;
  IF n_issues <> 6 THEN
    RAISE EXCEPTION 'Secure America pass: expected 6 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_parent <> 2 THEN
    RAISE EXCEPTION 'Secure America pass: expected all 2 amendments linked to their S. 2 parent, found % link(s)', n_parent;
  END IF;
  IF n_enacted <> 1 THEN
    RAISE EXCEPTION 'Secure America pass: S. 2 is not recorded as enacted law 119-98 (found % row(s))', n_enacted;
  END IF;
END $$;
